<template>
  <div class="autocomplete">
    <input id="typeBox" type="text" class="type" tabindex="-1" :value="type" @input="onInput"
           @keydown.down="onArrowDown" @keydown.up="onArrowUp" @keydown.tab="onTab" @keyup.enter="$emit('sendMsg')">
    <transition name="slide-fade">
      <div class="autocomplete-results-wrap" v-show="isOpenAutoComplete">
        <ul id="autocomplete-results" class="autocomplete-results">
          <li v-for="(result, i) in foundCommands" :key="i" @click="setInput(`/${result.CommandText}`)"
              class="autocomplete-result"
              :class="{ 'is-active': i === arrowCounter }">
            {{ result.CommandText }}
            <div class="params">
              <div class="param" v-for="(param, i) in result.Parameters" :class="{ 'param-active': i === activeParam }"
                   :key="param">{{ param }}
              </div>
            </div>
          </li>
        </ul>
      </div>
    </transition>
  </div>
</template>

<script>
export default {
  name: "chat-input",
  emits: ["update:type", "update:isOpenAutoComplete", "sendMsg", "historyUp", "historyDown"],
  props: {
    type: String,
    foundCommands: Array,
    isOpenAutoComplete: Boolean
  },
  data() {
    return {
      arrowCounter: 0,
      activeParam: -1,
    }
  },
  methods: {
    onInput(e) {
      const text = e.target.value;
      this.activeParam = (this.foundCommands.length > 0 ? (text.split(' ').length - 2 >= this.foundCommands[this.arrowCounter].Parameters.length ? this.foundCommands[this.arrowCounter].Parameters.length - 1 : text.split(' ').length - 2) : -1)
      this.setInput(text);
    },
    setInput(text) {
      this.$emit('update:type', text)
    },
    onArrowUp(e) {
      e.preventDefault();
      if (this.isOpenAutoComplete && this.foundCommands.length > 1) {
        if (this.arrowCounter > 0) {
          this.arrowCounter = this.arrowCounter - 1;
        } else {
          this.arrowCounter = this.foundCommands.length - 1;
        }
      } else {
        this.$emit("historyUp");
      }
    },
    onArrowDown(e) {
      e.preventDefault();
      if (this.isOpenAutoComplete && this.foundCommands.length > 1) {
        if (this.arrowCounter < this.foundCommands.length - 1) {
          this.arrowCounter = this.arrowCounter + 1;
        } else {
          this.arrowCounter = 0;
        }
      } else {
        this.$emit("historyDown");
      }
    },
    onTab(e) {
      e.preventDefault();
      if (!this.isOpenAutoComplete || this.foundCommands[0] === this.type) return;
      this.setInput(`/${this.foundCommands[this.arrowCounter].CommandText}`)
      //this.$emit('update:isOpenAutoComplete', false)
      this.arrowCounter = 0;
    },
  }
}
</script>

<style lang="scss" scoped>
.slide-fade-enter-active {
  transition: all 0.3s ease-out;
}

.slide-fade-leave-active {
  transition: all 0.4s cubic-bezier(1, 0.5, 0.8, 1);
}

.slide-fade-enter-from,
.slide-fade-leave-to {
  transform: translateY(20px);
  opacity: 0;
}

.autocomplete {
  position: relative;
  width: 100%;
  overflow: visible;

  input {
    width: 100%;
    background: rgba($background, 0.1);
    border: 1.5px solid rgba($blue, 0.5);
    border-bottom-left-radius: 5px;
    border-bottom-right-radius: 5px;
    padding: 5px 10px;
    font-weight: bold;
    color: rgba($white-text, 0.9);

    &:focus {
      outline: none;
    }
  }
}

.autocomplete-results-wrap {
  position: absolute;
  margin: 0;
  border-radius: 5px;
  background: rgba($background, 0.9);
  padding: 5px;
  width: 100%;
  top: 32px;
}

.autocomplete-results {
  overflow: auto;
}

.autocomplete-result {
  list-style: none;
  text-align: left;
  padding: 5px 10px;
  cursor: pointer;
  color: $white-text;
  border-radius: 5px;
  margin: 2px 0;
  font-weight: bold;
  font-size: 13px;
  display: flex;
  justify-content: flex-start;
  align-items: center;

  .params {
    margin-left: 1px;
    display: flex;

    .param {
      margin: 0 2px;
      background: rgba($foreground, 0.9);
      border-radius: 5px;
      padding: 2px 5px;
      font-size: 12px;
      color: darken($white-text, 15%)
    }
  }
}

.is-active {
  .params {
    .param-active {
      background: rgba(lighten($gray, 10%), 0.7) !important;
    }
  }
}

.autocomplete-result.is-active,
.autocomplete-result:hover {
  background-color: rgba($blue, 0.3);
  color: rgba($blue, 0.9);
}

</style>