<template>
  <div class="msg">
    <div :id="timestamp">
    </div>
  </div>
</template>

<script>
import $ from "jquery";
import dayjs from "dayjs";

export default {
  name: "chat-message",
  props: {
    message: {
      type: String,
      required: true
    }
  },
  data() {
    return {
      timestamp: Date.now()
    }
  },
  methods: {
    escapeHtml(unsafe) {
      return unsafe.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#039;');
    }
  },
  mounted() {
    let chat = $(`#${this.timestamp}`);

    let colorPositions = [];
    let colors = [];
    let chatElement = "<div>";
    let text = "!{#FFFFFF}" + this.escapeHtml(this.message);
    for (let i = 0; i < text.length; i++
    ) {
      let colorCheck = `${text[i]}${text[i + 1]}${text[i + 2]}`;

      if (colorCheck === "!{#") {
        colorPositions.push(i);
      }
    }

    colorPositions.forEach(el => {
      let sub = text.slice(el, -1);
      colors.push(sub.slice(3, 9));
    });

    colorPositions.forEach((el, i) => {
      let sub = text.slice(colorPositions[i] + 10, colorPositions[i + 1]);
      chatElement += `<span style='color: #${colors[i]}'>${sub}</span>`;
    });

    chatElement += "</div>";

    if (chatElement === "<div></div>") {
      chat.prepend("<div>" + text + "</div>");
    } else {
      chat.prepend(chatElement);
    }
  }
}
</script>

<style lang="scss" scoped>
.msg {
  word-break: break-all;

  .timestamp {
    margin-right: 5px;
    color: $white-text;
    font-weight: bold;
    min-width: max-content;
  }

  .author {
    margin-right: 5px;
    min-width: max-content;
    font-weight: bold;
  }
  li {
    list-style: none;
  }
}
</style>