<template>
  <div className="panel">
    <div v-if="monitor" class="fps">{{ animatedNumberFps }}<i class="fa-solid fa-bolt"></i></div>
    <div v-if="monitor" class="fps">{{ animatedNumberPing }}<i class="fa-solid fa-signal"></i></div>
    <div className="points">{{ animatedNumber }}<i class="fa-solid fa-coins"></i></div>
    <div className="currentLobby"><span>LID:</span> {{ stats.lobby }}</div>
    <div className="timeDate"><i class="fa-solid fa-clock"></i>{{ time }} {{ date }}</div>
    <img src="https://i.imgur.com/S9m1NVy.png" alt="logo" className="logo">
  </div>
</template>

<script>
import gsap from "gsap";

export default {
  name: "Info",
  data() {
    return {
      monitor: false,
      time: '',
      date: '',
      timer: null,
      fps: 92,
      tweenedFps: 92,
      ping: 12,
      tweenedPing: 12,
      points: 2322,
      tweenedPoints: 2322,
    }
  },
  props: ['stats'],
  watch: {
    points(newValue) {
      gsap.to(this.$data, { duration: 0.5, tweenedPoints: newValue })
    },
    fps(newValue) {
      gsap.to(this.$data, { duration: 0.5, tweenedFps: newValue })
    },
    ping(newValue) {
      gsap.to(this.$data, { duration: 0.5, tweenedPing: newValue })
    }
  },
  computed: {
    animatedNumber() {
      return this.tweenedPoints.toFixed(0)
    },
    animatedNumberFps() {
      return this.tweenedFps.toFixed(0)
    },
    animatedNumberPing() {
      return this.tweenedPing.toFixed(0)
    },
  },
  methods: {
    startClock() {
      this.updateClock();
      this.timer = setInterval(this.updateClock, 60000);
    },
    zeroPadding(num, digit) {
      let zero = '';
      for (let i = 0; i < digit; i++) {
        zero += '0';
      }
      return (zero + num).slice(-digit);
    },
    updateClock() {
      let cd = new Date();
      this.time = this.zeroPadding(cd.getHours(), 2) + ':' + this.zeroPadding(cd.getMinutes(), 2); // + ':' + this.zeroPadding(cd.getSeconds(), 2)
      this.date = this.zeroPadding(cd.getDate(), 2) + '.' + this.zeroPadding(cd.getMonth() + 1, 2) + '.' + this.zeroPadding(cd.getFullYear(), 4);
    }
  },
  mounted() {
    this.startClock()
  }
}
</script>

<style scoped lang="scss">

.panel {
  padding: 5px 10px;
  height: 35px;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: 10px;
  color: rgba($white-text, 0.8);
  font-size: 15px;
  background: rgba($background, 0.4);
  font-family: 'Nunito', sans-serif;
  font-weight: bold;
  margin-bottom: 5px;

  .fps {
    margin-right: 15px;
    display: flex;
    justify-content: center;
    align-items: center;

    .fa-solid {
      font-size: 17px;
      margin-left: 5px;
    }
  }

  .points {
    margin-right: 15px;
    display: flex;
    justify-content: center;
    align-items: center;

    .fa-solid {
      font-size: 17px;
      margin-left: 2px;
      //color: rgba(252, 209, 106, 0.8);
    }

  }

  .currentLobby {
    margin-right: 15px;

    span {
      color: rgba($white-text, 0.5);
    }
  }

  .timeDate {
    display: flex;
    justify-content: center;
    align-items: center;
    margin: 0px 10px 0px 0px;

    .fa-solid {
      font-size: 17px;
      margin-right: 2px;
    }
  }

  .logo {
    width: 37px;
    height: 37px;
  }
}

</style>